"""Publication guard shared with the isolated translation runtime."""
OUTPUT_CODE = 'import re, unicodedata\n\ndef normalize_translation_output(source, value):\n    if not isinstance(value,str) or not value.strip():\n        raise RuntimeError(\'Tradução vazia; TXT anterior preservado.\')\n    value=value.strip()\n    def norm(text):return \' \'.join(unicodedata.normalize(\'NFC\',text).split())\n    wrapper=re.fullmatch(r\'["“](.+?)["”]\\s+translates\\s+to\\s+["“](.+)["”]\\s*[.]?\',value,re.I|re.S)\n    warnings=[]\n    if wrapper:\n        if norm(wrapper[1])!=norm(source):\n            raise RuntimeError(\'Resposta explicativa com origem diferente; confira a tradução. TXT anterior preservado.\')\n        value=wrapper[2].strip()\n        warnings.append(\'Apresentação do tradutor removida; confira a tradução extraída.\')\n    meta=r\'\\btranslates\\s+to\\b|^\\s*(?:here\\s+is\\s+(?:the|your)\\s+translation|the\\s+translation\\s+of|translation\\s*:|a\\s+tradução\\s+(?:é|de)|tradução\\s*:)|```\'\n    if re.search(meta,value,re.I) and not re.search(meta,source,re.I):\n        raise RuntimeError(\'Tradutor retornou comentários em vez de somente fala; resultado REVISAR, TXT anterior preservado.\')\n    return value,warnings\n'
exec(OUTPUT_CODE)
